use std::sync::OnceLock;

fn schema() -> String {
    let mut out=concat!(
        "% schema.pl: the comparison and arithmetic built-ins of the compiled Prolog schema (docs/REFERENCE.md); generated by ckc from the formal specification; do not edit; first-party code, Apache-2.0 WITH LLVM-exception.\n",
        "guideline_satisfies(S, N, B, M) :- atom(S), atom(B), guideline_number(N, P, Q), guideline_number(M, R, T), X is P * T, Y is R * Q, guideline_within(S, X, B, Y).\n",
        "guideline_satisfies(S, N, U, B, M, V) :- atom(S), atom(U), atom(B), atom(V), guideline_number(N, P, Q), guideline_number(M, R, T), guideline_scale(U, G, A), guideline_scale(V, G, C), X is P * A * T, Y is R * C * Q, guideline_within(S, X, B, Y).\n",
        "guideline_product(S1, N1, S2, N2, S, N) :- guideline_set(S1, N1, A), guideline_set(S2, N2, B), guideline_times(A, B, C), guideline_spell(C, S0, N0), S = S0, N = N0.\n",
        "guideline_quotient(S1, N1, S2, N2, S, N) :- guideline_set(S1, N1, A), guideline_set(S2, N2, B), guideline_inverse(B, D), guideline_times(A, D, C), guideline_spell(C, S0, N0), S = S0, N = N0.\n",
        "guideline_number(N, N, 1) :- integer(N).\n",
        "guideline_number(N, P, Q) :- compound(N), functor(N, rational, 2), arg(1, N, P), arg(2, N, Q), integer(P), integer(Q), Q >= 2, A is abs(P), guideline_gcd(A, Q, 1).\n",
        "guideline_gcd(A, 0, A).\n",
        "guideline_gcd(A, B, G) :- B > 0, C is A mod B, guideline_gcd(B, C, G).\n",
        "guideline_set(S, N, V) :- atom(S), guideline_number(N, P, Q), guideline_ray(S, P, Q, V).\n",
        "guideline_ray(exactly, P, Q, point(P, Q)).\n",
        "guideline_ray(eq, P, Q, lower(P, Q, true)).\n",
        "guideline_ray(geq, P, Q, lower(P, Q, true)).\n",
        "guideline_ray(greater, P, Q, lower(P, Q, false)).\n",
        "guideline_ray(leq, P, Q, upper(P, Q, true)).\n",
        "guideline_ray(less, P, Q, upper(P, Q, false)).\n",
        "guideline_times(point(X, _), _, point(0, 1)) :- X =:= 0.\n",
        "guideline_times(A, point(Y, _), point(0, 1)) :- Y =:= 0, guideline_nonzero(A).\n",
        "guideline_times(point(X, D), B, C) :- X =\\= 0, guideline_nonzero(B), guideline_stretch(X, D, B, C).\n",
        "guideline_times(A, point(Y, E), C) :- Y =\\= 0, guideline_ray_kind(A), guideline_stretch(Y, E, A, C).\n",
        "guideline_times(lower(X, D, F), lower(Y, E, G), lower(Z, W, K)) :- X >= 0, Y >= 0, Z is X * Y, W is D * E, guideline_att(X, F, Y, G, K).\n",
        "guideline_times(upper(X, D, F), upper(Y, E, G), lower(Z, W, K)) :- X =< 0, Y =< 0, Z is X * Y, W is D * E, guideline_att(X, F, Y, G, K).\n",
        "guideline_times(lower(X, D, F), upper(Y, E, G), upper(Z, W, K)) :- X >= 0, Y =< 0, Z is X * Y, W is D * E, guideline_att(X, F, Y, G, K).\n",
        "guideline_times(upper(X, D, F), lower(Y, E, G), upper(Z, W, K)) :- X =< 0, Y >= 0, Z is X * Y, W is D * E, guideline_att(X, F, Y, G, K).\n",
        "guideline_nonzero(point(X, _)) :- X =\\= 0.\n",
        "guideline_nonzero(lower(_, _, _)).\n",
        "guideline_nonzero(upper(_, _, _)).\n",
        "guideline_ray_kind(lower(_, _, _)).\n",
        "guideline_ray_kind(upper(_, _, _)).\n",
        "guideline_stretch(X, D, point(Y, E), point(Z, W)) :- Z is X * Y, W is D * E.\n",
        "guideline_stretch(X, D, lower(Y, E, F), lower(Z, W, F)) :- X > 0, Z is X * Y, W is D * E.\n",
        "guideline_stretch(X, D, lower(Y, E, F), upper(Z, W, F)) :- X < 0, Z is X * Y, W is D * E.\n",
        "guideline_stretch(X, D, upper(Y, E, F), upper(Z, W, F)) :- X > 0, Z is X * Y, W is D * E.\n",
        "guideline_stretch(X, D, upper(Y, E, F), lower(Z, W, F)) :- X < 0, Z is X * Y, W is D * E.\n",
        "guideline_att(_, true, _, true, true).\n",
        "guideline_att(X, true, _, false, K) :- guideline_zero(X, K).\n",
        "guideline_att(_, false, Y, true, K) :- guideline_zero(Y, K).\n",
        "guideline_att(_, false, _, false, false).\n",
        "guideline_zero(X, true) :- X =:= 0.\n",
        "guideline_zero(X, false) :- X =\\= 0.\n",
        "guideline_inverse(point(Y, E), point(E, Y)) :- Y > 0.\n",
        "guideline_inverse(point(Y, E), point(F, Z)) :- Y < 0, F is -E, Z is -Y.\n",
        "guideline_spell(point(P, Q), exactly, N) :- guideline_canon(P, Q, N).\n",
        "guideline_spell(lower(P, Q, true), geq, N) :- guideline_canon(P, Q, N).\n",
        "guideline_spell(lower(P, Q, false), greater, N) :- guideline_canon(P, Q, N).\n",
        "guideline_spell(upper(P, Q, true), leq, N) :- guideline_canon(P, Q, N).\n",
        "guideline_spell(upper(P, Q, false), less, N) :- guideline_canon(P, Q, N).\n",
        "guideline_canon(P, Q, N) :- A is abs(P), guideline_gcd(A, Q, G), R is P // G, T is Q // G, guideline_make(R, T, N).\n",
        "guideline_make(P, 1, P).\n",
        "guideline_make(P, Q, rational(P, Q)) :- Q > 1.\n"
    ).to_string();
    for (stated, bound, op) in [
        ("eq", "geq", ">="),
        ("exactly", "geq", ">="),
        ("geq", "geq", ">="),
        ("greater", "geq", ">="),
        ("eq", "greater", ">"),
        ("exactly", "greater", ">"),
        ("geq", "greater", ">"),
        ("greater", "greater", ">="),
        ("exactly", "leq", "=<"),
        ("leq", "leq", "=<"),
        ("less", "leq", "=<"),
        ("exactly", "less", "<"),
        ("leq", "less", "<"),
        ("less", "less", "=<"),
        ("exactly", "exactly", "=:="),
    ] {
        out.push_str(&format!(
            "guideline_within({stated}, X, {bound}, Y) :- X {op} Y.\n"
        ));
    }
    for (u, g, r) in [
        ("second", "time", 1),
        ("minute", "time", 60),
        ("hour", "time", 3600),
        ("day", "time", 86400),
        ("week", "time", 604800),
        ("month", "calendar", 1),
        ("year", "calendar", 12),
    ] {
        out.push_str(&format!("guideline_scale({u}, {g}, {r}).\n"));
    }
    out
}
fn check_results() -> &'static BTreeMap<&'static str, Run> {
    static R: OnceLock<BTreeMap<&'static str, Run>> = OnceLock::new();
    R.get_or_init(||{
        let scratch=Scratch::new("schema-check");let head=git(&root(),&["rev-parse","HEAD"]);
        git(&scratch.0,&["clone","-q","--shared","--no-checkout",root().to_str().unwrap(),"tree"]);
        let tree=scratch.0.join("tree");git(&tree,&["checkout","-q","--detach",head.trim()]);
        let swipl=scratch.0.join("stop-before-ape");write(&swipl,"#!/bin/sh\n[ \"$1\" = --version ] && { echo 'SWI-Prolog version 9.2.9 for x86_64-linux'; exit 0; }\necho 'nt1 fixture: reached APE stage' >&2\nexit 39\n");
        fs::set_permissions(&swipl,fs::Permissions::from_mode(0o755)).unwrap();
        let mut results=BTreeMap::new();
        for mutation in ["regular","absent","stale","symlink","directory","extra"] {
            git(&tree,&["reset","-q","--hard",head.trim()]);git(&tree,&["clean","-q","-f","-d","-x"]);
            let path=tree.join("guidelines/schema.pl");write(&path,schema());
            match mutation {
                "regular"=>(),
                "absent"=>fs::remove_file(&path).unwrap(),
                "stale"=>{let mut bytes=fs::read(&path).unwrap();let i=bytes.iter().position(|b|*b==b'c').unwrap();bytes[i]=b'C';fs::write(&path,bytes).unwrap();}
                "symlink"=>{let target=scratch.0.join("schema-target.pl");write(&target,schema());fs::remove_file(&path).unwrap();symlink(&target,&path).unwrap();}
                "directory"=>{fs::remove_file(&path).unwrap();fs::create_dir(&path).unwrap();}
                "extra"=>write(&tree.join("guidelines/nt1-extra.txt"),"extra root member\n"),
                _=>unreachable!(),
            }
            let out=Command::new("timeout").args(["--kill-after=2","90"]).arg(program()).arg("check")
                .current_dir(&tree).env("SWIPL",&swipl).env("CKC_JOBS","1").env("LC_ALL","C.UTF-8")
                .env("GIT_CONFIG_GLOBAL","/dev/null").env("GIT_CONFIG_SYSTEM","/dev/null").output().unwrap();
            results.insert(mutation,out.into());
        }
        results
    })
}
fn check_mutant(name: &str, classes: &[&str]) {
    let got = &check_results()[name];
    let diagnostic = got.violation();
    let path = if name == "extra" {
        "nt1-extra.txt"
    } else {
        "schema.pl"
    };
    assert!(
        got.rc == Some(1)
            && diagnostic.contains(path)
            && classes
                .iter()
                .any(|s| diagnostic.to_lowercase().contains(s)),
        "P5 {name}: expected rc=1 diagnostic path={path} class={classes:?}; got rc={:?}, violation={diagnostic:?}",
        got.rc
    );
}
#[test]
fn p5_check_schema_absent() {
    check_mutant("absent", &["missing", "absent", "not found", "no such"]);
}
#[test]
fn p5_check_schema_one_byte_stale() {
    check_mutant("stale", &["stale", "mismatch", "differ", "bytes"]);
}
#[test]
fn p5_check_schema_symlink() {
    check_mutant("symlink", &["regular", "symlink"]);
}
#[test]
fn p5_check_schema_directory() {
    check_mutant(
        "directory",
        &["regular", "directory", "invalid guideline id"],
    );
}
#[test]
fn p5_check_exact_regular_schema_reaches_ape_stage() {
    let got = &check_results()["regular"];
    assert_eq!(
        (got.rc, got.violation()),
        (Some(39), "nt1 fixture: reached APE stage"),
        "D10 exact regular common member admitted: {got:?}"
    );
}
#[test]
fn p5_check_extra_guidelines_root_member() {
    check_mutant("extra", &["directory", "unexpected", "entry"]);
}

const REVIEW: &str = "# format: docid<TAB>ace_sha256<TAB>coverage_row_sha256<TAB>region_payload_sha256<TAB>semantic_clause_sha256<TAB>review_sha256\n# bundle v2; review_sha256 = sha256 of the labeled component-digest block; regenerate: ckc review-manifest <id>; do not edit.\n";
fn document() -> String {
    format!(
        "% d.pl numeric fixture.\n{}guideline_schema_version(1).\nguideline_document(d,ace_sha256('{}'),ulex(none),vocabulary(none)).\n% S1: A patient has exactly 1 week.\nguideline_entity(actual,p,patient,countable).\nguideline_cardinality(actual,q,na,exactly,1).\nguideline_unit(actual,q,week).\nguideline_property(actual,p,eligible,pos) :- guideline_cardinality(actual,q,na,A,B), guideline_unit(actual,q,C), guideline_satisfies(A,B,C,greater,3,day).\n",
        model::declarations(true),
        "0".repeat(64)
    )
}
fn make_repo(scratch: &Path, profile: &str) -> PathBuf {
    let tree = scratch.join("repo");
    fs::create_dir(&tree).unwrap();
    git(&tree, &["init", "-q", "-b", "main"]);
    write(
        &tree.join("docs/REFERENCE.md"),
        "# Fixture\n\n## Compiled Prolog schema (v1)\n\nLoad guidelines/schema.pl before a document.\n\n## Operating\n\nFixture.\n",
    );
    write(&tree.join("NOTICE"), "Numeric fixture.\n");
    write(&tree.join("LICENSE"), "Numeric fixture license.\n");
    write(
        &tree.join("vendor/ape/prolog/ace_to_pl.pl"),
        "% fixture compiler\n",
    );
    write(
        &tree.join("vendor/clex/clex_lexicon.pl"),
        "% fixture lexicon\n",
    );
    write(&tree.join("guidelines/schema.pl"), schema());
    let g = tree.join("guidelines/alpha");
    write(
        &g.join("rights.tsv"),
        format!(
            "profile\tstatement\turl\tretrieved\tnote\n{profile}\tFixture rights.\thttps://example.invalid/alpha\t2026-01-01\tFixture.\n"
        ),
    );
    write(
        &g.join("README.md"),
        "# Alpha\n\n## Rights and attribution\n\nFixture.\n",
    );
    write(&g.join("ace/d.ace"), "A patient has a week.\n");
    write(&g.join("pl/d.pl"), document());
    write(&g.join("source/original.txt"), "Fixture source.\n");
    let components = ["ace", "coverage", "payload", "clauses"].map(|name| sha(name.as_bytes()));
    let block = format!(
        "bundle v2 d\nace {}\ncoverage {}\npayload {}\nclauses {}\n",
        components[0], components[1], components[2], components[3]
    );
    write(
        &g.join("audit/review-manifest.tsv"),
        format!(
            "{REVIEW}d\t{}\t{}\n",
            components.join("\t"),
            sha(block.as_bytes())
        ),
    );
    git(&tree, &["add", "-A"]);
    git(&tree, &["commit", "-q", "-m", "numeric fixture corpus"]);
    native(&tree, &["release-manifest"]).require_ok("release-manifest with common schema");
    git(&tree, &["add", "release-manifest.tsv"]);
    git(&tree, &["commit", "-q", "-m", "numeric fixture manifest"]);
    tree
}
fn archive(tree: &Path, scratch: &Path) -> PathBuf {
    let dest = scratch.join("dist");
    native(tree, &["dist", "build", dest.to_str().unwrap()]).require_ok("numeric archive build");
    let archives = fs::read_dir(&dest)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.to_string_lossy().ends_with(".tar.gz"))
        .collect::<Vec<_>>();
    assert_eq!(archives.len(), 1);
    let extract = scratch.join("extract");
    fs::create_dir(&extract).unwrap();
    command(
        Path::new("tar"),
        scratch,
        &[
            "-xzf",
            archives[0].to_str().unwrap(),
            "-C",
            extract.to_str().unwrap(),
        ],
        "",
    )
    .require_ok("extract self-generated archive");
    let roots = fs::read_dir(&extract)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect::<Vec<_>>();
    assert_eq!(roots.len(), 1);
    roots[0].clone()
}
#[test]
fn p7_archive_literal_load_line_answers_numeric_query() {
    let scratch = Scratch::new("release-load");
    let tree = make_repo(&scratch.0, "redistributable");
    let bag = archive(&tree, &scratch.0);
    assert_eq!(
        read(&bag.join("data/guidelines/schema.pl")),
        schema(),
        "common schema bytes"
    );
    let manifest = read(&bag.join("release-manifest.tsv"));
    let rows = manifest
        .lines()
        .filter_map(|l| l.strip_prefix("meta\treplay\tload: "))
        .collect::<Vec<_>>();
    assert_eq!(rows.len(), 1);
    let load = rows[0]
        .replace("<guideline-id>", "alpha")
        .replace("<docid>", "d");
    let schema_at = load
        .find("data/guidelines/schema.pl")
        .expect("literal load line names common schema");
    let document_at = load
        .find("data/guidelines/alpha/pl/d.pl")
        .expect("literal load line names document");
    assert!(schema_at < document_at);
    let version = command(Path::new("swipl"), &bag, &["--version"], "");
    version.require_ok("SWI release smoke pin");
    assert!(version.stdout.contains("version 9.2.9 "));
    // Keep the published line literal; isolate startup files in the shell function.
    let script = format!("swipl() {{ command swipl -f none -F none \"$@\"; }}; {load}");
    let query = "(guideline_property(actual,p,eligible,pos), guideline_satisfies(exactly,18,month,geq,1,year), \\+ guideline_satisfies(exactly,45,day,geq,1,month) -> writeln(nt1_numeric_load_ok), halt(0) ; halt(7)).\n";
    let run = command(Path::new("sh"), &bag, &["-c", &script], query);
    run.require_ok("literal exported load + numeric query");
    assert_eq!(
        run.stdout.trim(),
        "nt1_numeric_load_ok",
        "numeric rule + cross-unit positive + cross-group negative"
    );
    let readme = read(&bag.join("README-dist.md"));
    assert!(
        readme.contains("schema.pl"),
        "consumer loading instructions"
    );
}
#[test]
fn p7_schema_is_common_payload_even_if_all_guidelines_restricted() {
    let scratch = Scratch::new("release-restricted");
    let tree = make_repo(&scratch.0, "restricted");
    let bag = archive(&tree, &scratch.0);
    assert_eq!(read(&bag.join("data/guidelines/schema.pl")), schema());
    assert!(!bag.join("data/guidelines/alpha").exists());
    let manifest = read(&bag.join("release-manifest.tsv"));
    assert!(
        manifest
            .lines()
            .any(|l| l.starts_with("member\tdata/guidelines/schema.pl\t"))
    );
}
